package require -exact qsys 24.1

proc range {n} {
   set l [list]
   for {set i 0} {$i < $n} {incr i} {
      lappend l $i
   }
   return $l
}

proc max {l} {
   set m 0
   foreach i $l {
      if {$i > $m} {
         set m $i
      }
   }
   return $m
}

proc lassign_helper {values args} {
   uplevel 1 [list foreach "$args" $values break]
}

proc list_unique {l} {
   if {[llength $l] == 0} {
      return $l
   }
   array set unique_arr [list]
   set unique_list      [list]
   foreach item $l {
      if {![info exists unique_arr($item)]} {
         set unique_arr($item) 1
         lappend unique_list $item
      }
   }
   unset unique_arr
   return $unique_list
}

proc string_map {mapping str} {
   foreach {subst_this subst_with} $mapping {
      set start [string first $subst_this $str]
      if {$start != -1} {
         set end   [expr { $start + [string length $subst_this] }]
         set left  [string range $str 0 [expr {$start - 1}]]
         set right [string range $str $end end]
         set str   "${left}${subst_with}${right}"
      }
   }
   return $str
}

proc parray_helper {arr} {
   upvar $arr $arr
   if {[llength [array names $arr]] == 0} {
   } else {
      parray $arr
   }
}

proc serialize_arrays_to_list {args} {
   set separator "~"
   set flat_list [list]
   foreach arr $args {
      if {[llength $flat_list] == 0} {
         set flat_list [concat $flat_list                   [uplevel 1 [list array get $arr]] ]
      } else {
         set flat_list [concat $flat_list [list $separator] [uplevel 1 [list array get $arr]] ]
      }
   }

   if {0} {
      puts "***** serialize_arrays_to_list *****"
      foreach arr $args {
         uplevel 1 [list parray $arr]
         puts ""
      }
      puts "**************************************"
   }

   return $flat_list
}

proc deserialize_list_to_arrays {flat_list args} {
   set separator "~"
   foreach sub_list [split $flat_list $separator] \
           arr      $args {
      uplevel 1 "if {\[info exists $arr\]} { array unset $arr }; array set $arr \[list $sub_list\]"
   }

   if {0} {
      puts "***** deserialize_list_to_arrays *****"
      foreach arr $args {
         uplevel 1 [list parray_helper $arr]
         puts ""
      }
      puts "**************************************"
   }
}

proc gets_helper {func var_key_pairs} {
   set keys [list]
   foreach {var key} $var_key_pairs {
      lappend keys $key
   }
   set vals [$func $keys]
   foreach {var key} $var_key_pairs val $vals {
      uplevel 1 [list set $var $val]
   }
}

proc enable_and_load_component {inst_name {requires_sysinfo true}} {
   set_instance_property $inst_name ENABLED true
   load_component $inst_name
   if {[string is true $requires_sysinfo]} {
      sync_component_sysinfo_parameters
   }
}

proc enable_without_load_component {inst_name {requires_sysinfo true}} {
   set_instance_property $inst_name ENABLED true
   if {[string is true $requires_sysinfo]} {
      sync_sysinfo_parameters $inst_name
   }
}

proc save_component_helper {inst_name} {
   set msgs ""
   foreach msg [validate_component] {
      if {[string first "Error:" $msg] != -1} {
         append msgs "${inst_name}: ${msg}\n"
      }
   }
   save_component
   if {$msgs != ""} {
      error [string trim $msgs "\n"]
   }
}

proc set_hwtcl_parameter_property {instance parameter property value} {
   variable hwtcl_cmds
   lappend hwtcl_cmds "set_instance_package_parameter_property $instance $parameter $property $value"
}

proc get_unconnected_interfaces {} {
   foreach connection [get_connections] {
      set from  [lindex [split $connection "/"] 0]
      set to    [lindex [split $connection "/"] 1]
      set connected_ifs($from) 1
      set connected_ifs($to) 1
   }

   foreach interface [get_interfaces] {
      set sub_if [get_interface_property $interface EXPORT_OF]
      set connected_ifs($sub_if) 1
   }

   foreach {portname expression} [get_wirelevel_expressions] {
      set ip_port [lindex [split $portname "\["] 0]
      set ip      [lindex [split $ip_port  "." ] 0]
      set port    [lindex [split $ip_port  "." ] 1]
      set sub_if ""
      foreach if_name [get_instance_interfaces $ip] {
         foreach port_name [get_instance_interface_ports $ip $if_name] {
            if {$port_name == $port} {
               set sub_if "${ip}.${if_name}"
               break
            }
         }
      }
      if {$sub_if != ""} {
         set connected_ifs($sub_if) 1
      }
   }

   set unconnected_ifs [list]
   foreach instance [get_instances] {
      if {[get_instance_property $instance ENABLED]} {
         foreach interface [get_instance_interfaces $instance] {
            set sub_if "${instance}.${interface}"
            if {![info exists connected_ifs($sub_if)]} {
               lappend unconnected_ifs $sub_if
            }
         }
      }
   }

   return $unconnected_ifs
}

proc export_interfaces {} {
   upvar rename_rules rename_rules
   upvar rename_vars rename_vars

   foreach sub_if [get_unconnected_interfaces] {
      lassign_helper [split $sub_if "."] instance interface

      if {[info exists rename_vars($instance)]} {
         set instance_rename_vars_list $rename_vars($instance)
      } else {
         set instance_rename_vars_list [list [list]]
      }
      set found 0
      foreach instance_rename_vars $instance_rename_vars_list {

         foreach k [array names rename_rules] {
            set key $k
            set k   [string_map $instance_rename_vars $k]
            if {[string match $k $sub_if]} {
               set found 1
               break
            }
         }
         if {!$found} {
            continue
         }

         lassign_helper $rename_rules($key) top_interface port_sub_this iport_sub_with oport_sub_with

         set top_interface  [string_map $instance_rename_vars $top_interface ]
         set port_sub_this  [string_map $instance_rename_vars $port_sub_this ]
         set iport_sub_with [string_map $instance_rename_vars $iport_sub_with]
         set oport_sub_with [string_map $instance_rename_vars $oport_sub_with]

         add_interface $top_interface "" ""
         set_interface_property $top_interface EXPORT_OF $sub_if

         set start [string length [lindex [split $port_sub_this "*"] 0]]
         set end   [string length [lindex [split $port_sub_this "*"] 1]]
         if {[string first "*" $port_sub_this] == -1} {
            set start 0
            set end   0
         }

         set port_renames [list]
         foreach port [get_instance_interface_ports $instance $interface] {
            set dir [get_instance_interface_port_property $instance $interface $port DIRECTION]
            set extract [string range $port $start end-$end]
            set new_top_port  [expr {[string tolower $dir] == "input" ? $iport_sub_with : $oport_sub_with}]
            regsub {\*}       $new_top_port $extract new_top_port
            set role [get_instance_interface_port_property $instance $interface $port ROLE]
            set default_top_port "${top_interface}_${role}"
            lappend port_renames $default_top_port $new_top_port
         }
         set_interface_ports_property $top_interface NAME $port_renames

         break
      }
      if {!$found} {
         puts "Internal Error: Failed to find rename_rules for $sub_if"
      }
   }
}

proc get_connected_source_if {ip_name if_name} {
   set dir [get_instance_interface_property $ip_name $if_name CLASS_NAME]
   if {$dir == "clock_sink" || $dir == "reset_sink"} {
      set conns [get_connections "${ip_name}.${if_name}"]
      if {[llength $conns] > 0} {
         set conn   [lindex $conns 0]
         set src_if [lindex [split $conn "/"] 0]
         return $src_if
      }
   } else {
      return "${ip_name}.${if_name}"
   }
   error "Internal Error: Unable to find connected clk/reset source for ${ip_name}.${if_name}"
}

proc connect_csr_interfaces {csr_initiator} {
   upvar csr_map csr_map

   foreach sub_if [get_unconnected_interfaces] {
      lassign_helper [split $sub_if "."] instance interface

      set found 0
      foreach k [array names csr_map] {
         if {[string match $k $sub_if]} {
            set key $k
            set found 1
            break
         }
      }
      if {!$found} {
         continue
      }

      if {![info exists intf_idxs($key)]} {
         set intf_idxs($key) 0
      } else {
         incr intf_idxs($key)
      }
      set intf_idx $intf_idxs($key)

      lassign_helper $csr_map($key) start_address address_incr use_bridge


      set from_if $csr_initiator
      set to_if   $sub_if

      set from_ip_name [lindex [split $from_if .] 0]
      set from_if_name [lindex [split $from_if .] 1]
      set to_ip_name   [lindex [split $to_if   .] 0]
      set to_if_name   [lindex [split $to_if   .] 1]

      set from_clk [get_instance_interface_property $from_ip_name $from_if_name associatedClock]
      set from_rst [get_instance_interface_property $from_ip_name $from_if_name associatedReset]
      set to_clk   [get_instance_interface_property $to_ip_name   $to_if_name   associatedClock]
      set to_rst   [get_instance_interface_property $to_ip_name   $to_if_name   associatedReset]

      set from_clk [get_connected_source_if $from_ip_name $from_clk]
      set from_rst [get_connected_source_if $from_ip_name $from_rst]
      set to_clk   [get_connected_source_if $to_ip_name   $to_clk  ]
      set to_rst   [get_connected_source_if $to_ip_name   $to_rst  ]


      set class_name [get_instance_interface_property $to_ip_name $to_if_name CLASS_NAME]
      switch -glob -- $class_name {
         avalon_* {
            set if_type        avalon
            set addr_port_role address
         }
         axi4_* -
         axi4lite_* {
            set if_type        axi
            set addr_port_role awaddr
         }
         apb_* {
            set if_type        apb
            set addr_port_role paddr
         }
         default {
            error "Internal Error: Unidentified CSR responder interface type $class_name"
         }
      }

      foreach if_port [get_instance_interface_ports $to_ip_name $to_if_name] {
         set if_port_role [get_instance_interface_port_property $to_ip_name $to_if_name $if_port ROLE]
         if {$if_port_role == $addr_port_role} {
            set addr_port_width [get_instance_interface_port_property $to_ip_name $to_if_name $if_port WIDTH]
            break
         }
      }



      if {$use_bridge && $from_clk != $to_clk} {
         if {$if_type == "avalon"} {
            if {![info exists bridge_idxs(csr_cdc)]} {
               set bridge_idxs(csr_cdc) 0
            } else {
               incr bridge_idxs(csr_cdc)
            }
            set bridge_name "csr_cdc_${bridge_idxs(csr_cdc)}"

            enable_and_load_component $bridge_name false
               set_component_parameter_values [list \
                  ADDRESS_WIDTH  $addr_port_width \
                  DATA_WIDTH     32 \
               ]
            save_component

            add_connection $from_clk ${bridge_name}.s0_clk
            add_connection $to_rst   ${bridge_name}.s0_reset
            add_connection $to_clk   ${bridge_name}.m0_clk
            add_connection $to_rst   ${bridge_name}.m0_reset

            add_connection ${bridge_name}.m0 $to_if

            set dst_if ${bridge_name}.s0
         } else {
            error "Internal Error: Unsupported CSR interface type $if_type for bridge insertion"
         }
      } elseif {$use_bridge && $from_clk == $to_clk} {
         if {$if_type == "avalon"} {
            if {![info exists bridge_idxs(csr_pipe)]} {
               set bridge_idxs(csr_pipe) 0
            } else {
               incr bridge_idxs(csr_pipe)
            }
            set bridge_name "csr_pipe_${bridge_idxs(csr_pipe)}"

            enable_and_load_component $bridge_name false
               set_component_parameter_values [list \
                  ADDRESS_WIDTH  $addr_port_width \
                  DATA_WIDTH     32 \
               ]
            save_component

            add_connection $from_clk ${bridge_name}.clk
            add_connection $from_rst ${bridge_name}.reset

            add_connection ${bridge_name}.m0 $to_if

            set dst_if ${bridge_name}.s0
         } else {
            error "Internal Error: Unsupported CSR interface type $if_type for bridge insertion"
         }
      } else {
         set dst_if $to_if
      }


      add_connection                 ${from_if} ${dst_if}
      set_connection_parameter_value ${from_if}/${dst_if} baseAddress [expr {$start_address + $intf_idx * $address_incr}]
      lock_avalon_base_address       $dst_if
   }
}



deserialize_list_to_arrays $__run_system_script_args_list__ param_value mem_conns app_conns mem_label app_label mem_ports app_ports

set messages ""

variable hwtcl_cmds [list]

set_validation_property AUTOMATIC_VALIDATION false

set_project_property DEVICE_FAMILY $param_value(SYSINFO_DEVICE_FAMILY)
set_project_property DEVICE        $param_value(SYSINFO_DEVICE)

remove_dangling_connections
remove_connections [get_connections]
remove_interfaces [get_interfaces]
foreach instance [get_instances] {
   set_instance_property $instance ENABLED false
}

set cmd_fail [catch { compose_ip } err_msg]


if {$cmd_fail} {
   append messages "${err_msg}\n"
}
if {!$cmd_fail} {
   foreach msg [validate_system] {
      if {[string first "Error:" $msg] != -1} {
         append messages "validate_system: ${msg}\n"
      }
   }
}

save_system

set messages_arr(messages) [string trimright $messages "\n"]
set hwtcl_cmds_arr(cmds)   $hwtcl_cmds
set __run_system_script_return_list__ [serialize_arrays_to_list messages_arr hwtcl_cmds_arr]

