proc compose_ip {} {
   upvar param_value param_value
   upvar mem_conns   mem_conns
   upvar app_conns   app_conns
   upvar mem_label   mem_label
   upvar app_label   app_label
   upvar mem_ports   mem_ports
   upvar app_ports   app_ports


   set rename_rules(emif_*.ref_clk)                         { "mem<MEM_ID>_pll_ref_clk"                  "*"               "mem<MEM_ID>_pll_ref_clk"           "mem<MEM_ID>_pll_ref_clk"           }
   set rename_rules(emif_*.mem_<IP_CH>)                     { "mem<MEM_ID><MEM_CH>_<PROTOCOL>"           "mem_<IP_CH>_*"   "mem<MEM_ID><MEM_CH>_<PROTOCOL>_*"  "mem<MEM_ID><MEM_CH>_<PROTOCOL>_*"  }
