   set rename_rules(hps_emif_refclk_bridge.refclk_in)       { "mem_hps_pll_ref_clk"                      "*"               "mem_hps_pll_ref_clk"               "mem_hps_pll_ref_clk"               }
   set rename_rules(hbm_*.uibpll_refclk)                    { "mem<MEM_ID>_pll_ref_clk"                  "*"               "mem<MEM_ID>_pll_ref_clk"           "mem<MEM_ID>_pll_ref_clk"           }
   set rename_rules(hbm_*.ch0_u0_wmc_intr)                  { "mem<MEM_ID>_pc0_wmc_intr"                 "ch0_u0_*"        "mem<MEM_ID>_pc0_*"                 "mem<MEM_ID>_pc0_*"                 }
   set rename_rules(hbm_*.ch0_u1_wmc_intr)                  { "mem<MEM_ID>_pc1_wmc_intr"                 "ch0_u1_*"        "mem<MEM_ID>_pc1_*"                 "mem<MEM_ID>_pc1_*"                 }
   set rename_rules(hbm_*.ch1_u0_wmc_intr)                  { "mem<MEM_ID>_pc2_wmc_intr"                 "ch1_u0_*"        "mem<MEM_ID>_pc2_*"                 "mem<MEM_ID>_pc2_*"                 }
   set rename_rules(hbm_*.ch1_u1_wmc_intr)                  { "mem<MEM_ID>_pc3_wmc_intr"                 "ch1_u1_*"        "mem<MEM_ID>_pc3_*"                 "mem<MEM_ID>_pc3_*"                 }
   set rename_rules(hbm_*.ch2_u0_wmc_intr)                  { "mem<MEM_ID>_pc4_wmc_intr"                 "ch2_u0_*"        "mem<MEM_ID>_pc4_*"                 "mem<MEM_ID>_pc4_*"                 }
   set rename_rules(hbm_*.ch2_u1_wmc_intr)                  { "mem<MEM_ID>_pc5_wmc_intr"                 "ch2_u1_*"        "mem<MEM_ID>_pc5_*"                 "mem<MEM_ID>_pc5_*"                 }
   set rename_rules(hbm_*.ch3_u0_wmc_intr)                  { "mem<MEM_ID>_pc6_wmc_intr"                 "ch3_u0_*"        "mem<MEM_ID>_pc6_*"                 "mem<MEM_ID>_pc6_*"                 }
   set rename_rules(hbm_*.ch3_u1_wmc_intr)                  { "mem<MEM_ID>_pc7_wmc_intr"                 "ch3_u1_*"        "mem<MEM_ID>_pc7_*"                 "mem<MEM_ID>_pc7_*"                 }
   set rename_rules(hbm_*.ch4_u0_wmc_intr)                  { "mem<MEM_ID>_pc8_wmc_intr"                 "ch4_u0_*"        "mem<MEM_ID>_pc8_*"                 "mem<MEM_ID>_pc8_*"                 }
   set rename_rules(hbm_*.ch4_u1_wmc_intr)                  { "mem<MEM_ID>_pc9_wmc_intr"                 "ch4_u1_*"        "mem<MEM_ID>_pc9_*"                 "mem<MEM_ID>_pc9_*"                 }
   set rename_rules(hbm_*.ch5_u0_wmc_intr)                  { "mem<MEM_ID>_pc10_wmc_intr"                "ch5_u0_*"        "mem<MEM_ID>_pc10_*"                "mem<MEM_ID>_pc10_*"                }
   set rename_rules(hbm_*.ch5_u1_wmc_intr)                  { "mem<MEM_ID>_pc11_wmc_intr"                "ch5_u1_*"        "mem<MEM_ID>_pc11_*"                "mem<MEM_ID>_pc11_*"                }
   set rename_rules(hbm_*.ch6_u0_wmc_intr)                  { "mem<MEM_ID>_pc12_wmc_intr"                "ch6_u0_*"        "mem<MEM_ID>_pc12_*"                "mem<MEM_ID>_pc12_*"                }
   set rename_rules(hbm_*.ch6_u1_wmc_intr)                  { "mem<MEM_ID>_pc13_wmc_intr"                "ch6_u1_*"        "mem<MEM_ID>_pc13_*"                "mem<MEM_ID>_pc13_*"                }
   set rename_rules(hbm_*.ch7_u0_wmc_intr)                  { "mem<MEM_ID>_pc14_wmc_intr"                "ch7_u0_*"        "mem<MEM_ID>_pc14_*"                "mem<MEM_ID>_pc14_*"                }
   set rename_rules(hbm_*.ch7_u1_wmc_intr)                  { "mem<MEM_ID>_pc15_wmc_intr"                "ch7_u1_*"        "mem<MEM_ID>_pc15_*"                "mem<MEM_ID>_pc15_*"                }
   set rename_rules(hbm_*.cattrip)                          { "mem<MEM_ID>_cattrip"                      "*"               "mem<MEM_ID>_*"                     "mem<MEM_ID>_*"                     }
   set rename_rules(hbm_*.cattrip_i)                        { "mem<MEM_ID>_cattrip_i"                    "*"               "mem<MEM_ID>_*"                     "mem<MEM_ID>_*"                     }
   set rename_rules(hbm_*.temp)                             { "mem<MEM_ID>_temp"                         "*"               "mem<MEM_ID>_*"                     "mem<MEM_ID>_*"                     }
   set rename_rules(hbm_*.temp_i)                           { "mem<MEM_ID>_temp_i"                       "*"               "mem<MEM_ID>_*"                     "mem<MEM_ID>_*"                     }
   set rename_rules(hbm_*.local_cal_success)                { "mem<MEM_ID>_cal_pass"                     "*"               "mem<MEM_ID>_cal_pass"              "mem<MEM_ID>_cal_pass"              }
   set rename_rules(hbm_*.local_cal_fail)                   { "mem<MEM_ID>_cal_fail"                     "*"               "mem<MEM_ID>_cal_fail"              "mem<MEM_ID>_cal_fail"              }
   set rename_rules(iniu_*.s0_axi4_aclk)                    { "i<APP_ID>_clk"                            "*"               "i<APP_ID>_app_ss_aclk"             "i<APP_ID>_ss_app_aclk"             }
   set rename_rules(iniu_*.s0_axi4_aresetn)                 { "i<APP_ID>_reset"                          "*"               "i<APP_ID>_app_ss_aresetn"          "i<APP_ID>_ss_app_aresetn"          }
   set rename_rules(iniu_*.s0_axi4)                         { "i<APP_ID>_axi_mm"                         "s0_axi4_*"       "i<APP_ID>_app_ss_mm_*"             "i<APP_ID>_ss_app_mm_*"             }
   set rename_rules(hbm_*_clk_bridge.in_clk)                { "i<APP_ID>_clk"                            "*"               "i<APP_ID>_app_ss_aclk"             "i<APP_ID>_ss_app_aclk"             }
   set rename_rules(mem_reset_bridge.in_reset)              { "mem<MEM_ID>_usr_reset_n"                  "*"               "mem<MEM_ID>_app_ss_usr_reset_n"    "mem<MEM_ID>_ss_app_usr_reset_n"    }
   set rename_rules(mem_reset_ctrl.subsystem_reset)         { "subsystem_reset"                          "*"               "*"                                 "*"                                 }




   set num_hpsemif 0
   set num_regemif 0
   set num_emif    0
   set num_hbm     0
   set num_iniu    0
   set num_cam     0
   set noc_ch      0

   array set mem_port__clk {}
   array set mem_port__rst {}
   array set mem_port__bus {}
   array set app_port__clk {}
   array set app_port__rst {}
   array set app_port__bus {}

   foreach mem_dev $param_value(MEM_INTFS_TYPE) \
           mem_idx $param_value(MEM_INTFS_IDX) {

      set not_connected [expr { [llength [array names mem_conns "m${mem_idx}_*"]] == 0 }]
      if {$not_connected} {
         continue
      }

      set connected_to_hps 0

      foreach {mem_port app_port_list} [array get mem_conns "m${mem_idx}_*"] {
         foreach app_port $app_port_list {
            if {$app_label($app_port) == "HPS"} {
               set connected_to_hps 1
            }
         }
      }

      switch -- $mem_dev {
         DDR5COMP -
         DDR5DIMM -
         DDR4COMP -
         DDR4DIMM -
         LPDDR5 -
         LPDDR5 {
            switch -- $mem_dev {
               DDR5COMP { set emif_name "emif_${num_emif}_ddr5comp";   set protocol "ddr5" }
               DDR5DIMM { set emif_name "emif_${num_emif}_ddr5dimm";   set protocol "ddr5" }
               DDR4COMP { set emif_name "emif_${num_emif}_ddr4comp";   set protocol "ddr4" }
               DDR4DIMM { set emif_name "emif_${num_emif}_ddr4dimm";   set protocol "ddr4" }
               LPDDR5   { set emif_name "emif_${num_emif}_lpddr5";     set protocol "lpddr5" }
               LPDDR4   { set emif_name "emif_${num_emif}_lpddr4";     set protocol "lpddr4" }
            }
            incr num_emif

            enable_and_load_component $emif_name
               gets_helper get_component_parameter_values [list \
                  prev_mainband_access_mode  PHY_MAINBAND_ACCESS_MODE \
               ]

               set_component_parameter_value IS_HPS $connected_to_hps
               if {$mem_dev == "DDR5COMP" || $mem_dev == "LPDDR5" || $mem_dev == "LPDDR4"} {
                  set num_channels      [llength [array names mem_conns "m${mem_idx}_*"]]
                  set num_channels_pow2 1
                  while {$num_channels_pow2 < $num_channels} { set num_channels_pow2 [expr {$num_channels_pow2 * 2}] }
                  set_component_parameter_value MEM_NUM_CHANNELS $num_channels_pow2
               }
               if {$param_value(ENABLE_NOC)} {
                  set_component_parameter_value PHY_MAINBAND_ACCESS_MODE "NOC"
                  set_component_parameter_value PHY_SIDEBAND_ACCESS_MODE "NOC"
                  set_hwtcl_parameter_property $emif_name PHY_MAINBAND_ACCESS_MODE DISABLED true
               } elseif {$connected_to_hps && 0} {
                  set_component_parameter_value PHY_MAINBAND_ACCESS_MODE "HARD_PATH"
                  set_component_parameter_value PHY_SIDEBAND_ACCESS_MODE "HARD_PATH"
                  set_hwtcl_parameter_property $emif_name PHY_MAINBAND_ACCESS_MODE DISABLED true
               } else {
                  if {$prev_mainband_access_mode != "SYNC" && $prev_mainband_access_mode != "ASYNC"} {
                     set_component_parameter_value PHY_MAINBAND_ACCESS_MODE "SYNC"
                  }
                  set_component_parameter_value PHY_SIDEBAND_ACCESS_MODE "FABRIC"
                  set_hwtcl_parameter_property $emif_name PHY_MAINBAND_ACCESS_MODE DISABLED false
               }
            save_component_helper $emif_name


            foreach mem_port [lsort [array names mem_conns "m${mem_idx}_*"]] {
               set mem_port_idx [string trimleft [lindex [split $mem_port "_"] 1] "p"]

               if {$connected_to_hps} {
                  set mem_port__clk($mem_port) "${emif_name}.refclk"
                  set mem_port__rst($mem_port) ""
                  set mem_port__bus($mem_port) ""
               } elseif {$param_value(ENABLE_NOC)} {
                  set mem_port__clk($mem_port) ""
                  set mem_port__rst($mem_port) ""
                  set mem_port__bus($mem_port) "${emif_name}.s${mem_port_idx}_noc_axi4noc"
               } else {
                  set mem_port__clk($mem_port) "${emif_name}.s_axi4_clock_out"
                  set mem_port__rst($mem_port) "${emif_name}.s_axi4_ctrl_ready"
                  set mem_port__bus($mem_port) "${emif_name}.s${mem_port_idx}_axi4"
               }

               if {$mem_dev ==  "DDR5DIMM" || $mem_dev == "DDR5COMP" || $mem_dev == "LPDDR5" || $mem_dev == "LPDDR4"} {
                  set ch_name "_ch${mem_port_idx}"
               } else {
                  set ch_name ""
               }

               set app_port [lindex $mem_conns(m${mem_idx}_p0) 0]
               set app_idx  [string trimleft [lindex [split $app_port "_"] 0] "a"]

               lappend rename_vars($emif_name) [list "<IP_CH>" $mem_port_idx "<MEM_ID>" $mem_idx "<MEM_CH>" $ch_name "<PROTOCOL>" $protocol "<APP_ID>" $app_idx "<NOC_CH>" $noc_ch]
               if {$connected_to_hps} {
                  incr noc_ch
               }
            }
         }
         HBM2E {
            set hbm_name "hbm_${num_hbm}"
            incr num_hbm

            enable_and_load_component $hbm_name
               set_component_parameter_values [list \
                  CTRL_CH0_EN    [expr { [info exists mem_conns(m${mem_idx}_p0)]  || [info exists mem_conns(m${mem_idx}_p1)]  }] \
                  CTRL_CH1_EN    [expr { [info exists mem_conns(m${mem_idx}_p2)]  || [info exists mem_conns(m${mem_idx}_p3)]  }] \
                  CTRL_CH2_EN    [expr { [info exists mem_conns(m${mem_idx}_p4)]  || [info exists mem_conns(m${mem_idx}_p5)]  }] \
                  CTRL_CH3_EN    [expr { [info exists mem_conns(m${mem_idx}_p6)]  || [info exists mem_conns(m${mem_idx}_p7)]  }] \
                  CTRL_CH4_EN    [expr { [info exists mem_conns(m${mem_idx}_p8)]  || [info exists mem_conns(m${mem_idx}_p9)]  }] \
                  CTRL_CH5_EN    [expr { [info exists mem_conns(m${mem_idx}_p10)] || [info exists mem_conns(m${mem_idx}_p11)] }] \
                  CTRL_CH6_EN    [expr { [info exists mem_conns(m${mem_idx}_p12)] || [info exists mem_conns(m${mem_idx}_p13)] }] \
                  CTRL_CH7_EN    [expr { [info exists mem_conns(m${mem_idx}_p14)] || [info exists mem_conns(m${mem_idx}_p15)] }] \
               ]
            save_component_helper $hbm_name


            foreach mem_port [lsort [array names mem_conns "m${mem_idx}_*"]] {
               set mem_port_idx  [string trimleft [lindex [split $mem_port "_"] 1] "p"]
               set num_pc_per_ch 2
               set hbm_ch        [expr {int($mem_port_idx / $num_pc_per_ch)}]
               set hbm_pc        [expr {int($mem_port_idx % $num_pc_per_ch)}]

               set mem_port__clk($mem_port) ""
               set mem_port__rst($mem_port) ""
               set mem_port__bus($mem_port) "${hbm_name}.t_ch${hbm_ch}_u${hbm_pc}_axi4noc"
            }

            lappend rename_vars($hbm_name) [list "<MEM_ID>" $mem_idx]
         }
         M20K {
            continue
         }
      }
   }


   foreach app_intf $param_value(APP_INTFS_TYPE) \
           app_idx  $param_value(APP_INTFS_IDX) {


      switch -- $app_intf {
         STORAGE {
            if {[string is false $param_value(ENABLE_NOC)]} {
               foreach {app_port mem_port_list} [array get app_conns "a${app_idx}_*"] {
                  set app_port__clk($app_port) ""
                  set app_port__rst($app_port) ""
                  set app_port__bus($app_port) ""
               }
            } else {
               set iniu_name "iniu_${num_iniu}"
               incr num_iniu

               enable_without_load_component $iniu_name false

               lappend rename_vars($iniu_name) [list "<APP_ID>" $app_idx]

               foreach {app_port mem_port_list} [array get app_conns "a${app_idx}_*"] {
                  set app_port__clk($app_port) ""
                  set app_port__rst($app_port) ""
                  set app_port__bus($app_port) ${iniu_name}.i0_axi4noc
               }
            }
         }
         HPS {
            enable_without_load_component hps_emif_refclk_bridge false
            enable_without_load_component hps_emif_refclk_gpio

            add_connection hps_emif_refclk_gpio.dout hps_emif_refclk_bridge.refclk_out_gpio
            add_connection hps_emif_refclk_bridge.refclk_in_gpio hps_emif_refclk_gpio.pad_in

            foreach {app_port mem_port_list} [array get app_conns "a${app_idx}_*"] {
               set app_port__clk($app_port) hps_emif_refclk_bridge.refclk_out
               set app_port__rst($app_port) ""
               set app_port__bus($app_port) ""
            }
         }
      }
   }


   set hbm_names_parsed [list]

   foreach {mem_port app_port_list} [array get mem_conns] {
      foreach app_port $app_port_list {
         if {$app_port__clk($app_port) != ""} { add_connection $app_port__clk($app_port) $mem_port__clk($mem_port) }
         if {$app_port__rst($app_port) != ""} { add_connection $app_port__rst($app_port) $mem_port__rst($mem_port) }
         if {$app_port__bus($app_port) != ""} { add_connection $app_port__bus($app_port) $mem_port__bus($mem_port) }

         set hbm_name  [lindex [split $mem_port__bus($mem_port) "."] 0]
         set iniu_name [lindex [split $app_port__bus($app_port) "."] 0]
         if {[string match "hbm_*" $hbm_name] && [lsearch -exact $hbm_names_parsed $hbm_name] == -1} {
            lappend hbm_names_parsed $hbm_name

            set clk_bridge "${hbm_name}_clk_bridge"
            enable_without_load_component $clk_bridge false

            add_connection ${clk_bridge}.out_clk  ${hbm_name}.fabric_clk
            add_connection ${clk_bridge}.out_clk  ${iniu_name}.s0_axi4_aclk

            set app_idx [string trimleft [lindex [split $app_port "_"] 0] "a"]
            lappend rename_vars($clk_bridge) [list "<APP_ID>" $app_idx]
         }
      }
   }

   if {$num_hbm > 0} {
      enable_and_load_component mem_reset_ctrl
         set_component_parameter_values [list \
            NUM_FP_HBM        $num_hbm  \
         ]
      save_component_helper mem_reset_ctrl

      enable_without_load_component mem_reset_bridge false

      add_connection hbm_0_clk_bridge.out_clk   mem_reset_ctrl.clk
      add_connection mem_reset_bridge.out_reset mem_reset_ctrl.reset


      for {set i 0} {$i < $num_hbm} {incr i} {
         add_connection mem_reset_ctrl.fp_hbm_reset_n_${i}    hbm_${i}.hbm_reset_n
         add_connection hbm_${i}.hbm_reset_in_prog            mem_reset_ctrl.fp_hbm_reset_in_prog_${i}
      }
   }


   auto_assign_system_base_addresses

   export_interfaces
}

