proc ::mem_ss_pkg::ip_mem_ss::example_design_fileset_callback {top_level_name} {
   variable mem_conns
   variable app_conns
   variable mem_label
   variable app_label
   variable mem_ports
   variable app_ports

   if {![pval RUN_COMPOSE]} {
      send_message error "IPs within Memory Subsystem are disabled. Please enable <b>'[pname RUN_COMPOSE]' (RUN_COMPOSE)</b> to enable the IPs."
      return
   }

   set curr_device_name [pval SYSINFO_DEVICE]

   if { [regexp  {^[ ]*$} $curr_device_name match] != 1 \
      && [string compare -nocase $curr_device_name "unknown"] != 0 \
      && [string first "LUDO" $curr_device_name ] == -1 } {
      set default_device $curr_device_name
   } else {
      set family         [table get device_features -> family -> VALUE]
      set default_device [table get family_features -> DEFAULT_DEVICE_FOR_ED -> $family]
   }

   set gen_sim   [pval EX_DESIGN_GEN_SIM]
   set gen_synth [pval EX_DESIGN_GEN_SYNTH]

   set tmp_path        [create_temp_file ""]

   set sim_qsys_name   "ed_sim"
   set sim_qsys_file   "${sim_qsys_name}.qsys"
   set sim_qsys_path   [file join $tmp_path "sim" $sim_qsys_file]
   set synth_qsys_name "ed_synth"
   set synth_qsys_file "${synth_qsys_name}.qsys"
   set synth_qsys_path [file join $tmp_path "synth" $synth_qsys_file]

   set design_types [list]
   if {$gen_sim} {
      file mkdir [file dirname $sim_qsys_path]
      lappend design_types "sim"
   }
   if {$gen_synth} {
      file mkdir [file dirname $synth_qsys_path]
      lappend design_types "synth"
   }

   set ip_inst [regsub -lineanchor "_example_design$" $top_level_name ""]

   set board_data_file [table get DIAG_EXTRA_PARAMETERS -> BOARD_DATA_FILE -> VALUE]
   if {$board_data_file == "NOVAL"} {
      set board_data_file ""
   }

   set params_file "params.tcl"
   set params_path [file join $tmp_path $params_file]
   set fh [open $params_path w]

   puts $fh "# This file is auto-generated."
   puts $fh ""

   foreach param [table rows parameters] {
      puts $fh "set ip_params(${param}) {[table get parameters -> $param -> VALUE]}"
   }

   foreach instance [get_all_enabled_instances] {
      set params [get_instance_parameters $instance]
      foreach param $params param_val [get_instance_parameter_values $instance $params] {
         set user_editable [get_instance_package_parameter_property $instance $param USER_EDITABLE]
         if {[string is true $user_editable]} {
            puts $fh "set ip_params(${instance}.${param}) {$param_val}"
         }
      }
   }

   puts $fh "set ip_params(RUN_COMPOSE)          {true}"

   puts $fh "set ed_params(IP_CORE)              {[lindex [table rows package] 0]}"
   puts $fh "set ed_params(IP_INST)              {$ip_inst}"
   puts $fh "set ed_params(DEFAULT_DEVICE)       {$default_device}"
   puts $fh "set ed_params(BOARD_DATA_FILE)      {$board_data_file}"
   puts $fh "set ed_params(SIM_QSYS_NAME)        {$sim_qsys_name}"
   puts $fh "set ed_params(TMP_SIM_QSYS_PATH)    {$sim_qsys_path}"
   puts $fh "set ed_params(SYNTH_QSYS_NAME)      {$synth_qsys_name}"
   puts $fh "set ed_params(TMP_SYNTH_QSYS_PATH)  {$synth_qsys_path}"
   puts $fh "set ed_params(HYDRA_HW_REGTEST)     {[qini_on memss_hydra_hw_regtest]}"
   puts $fh "set df_params(mem_conns)            {[array get mem_conns]}"
   puts $fh "set df_params(app_conns)            {[array get app_conns]}"
   puts $fh "set df_params(mem_label)            {[array get mem_label]}"
   puts $fh "set df_params(app_label)            {[array get app_label]}"
   puts $fh "set df_params(mem_ports)            {[array get mem_ports]}"
   puts $fh "set df_params(app_ports)            {[array get app_ports]}"
   foreach row [table rows device_features] {
      puts $fh "set device_features($row) {[table get device_features -> $row -> VALUE]}"
   }

   close $fh

   _add_ed_files [list $params_path [get_relative_path $tmp_path $params_path]]

   set qini_file "quartus.ini"
   set qini_path [file join $tmp_path $qini_file]
   set qini_src  [table get DIAG_EXTRA_PARAMETERS -> QUARTUS_INI_FILEPATH -> VALUE]
   if {$qini_src != "NOVAL"} {
      file copy -force $qini_src $qini_path
      _add_ed_files [list $qini_path [get_relative_path $tmp_path $qini_path]]
   }

   set qsys_script_exe_path  "$::env(QUARTUS_ROOTDIR)/sopc_builder/bin/qsys-script"
   set ip_root_path          "$::env(QUARTUS_ROOTDIR)/../ip/altera/subsystems/mem_ss_pkg"
   set ex_design_path        "${ip_root_path}/ip_mem_ss/ex_design"
   set make_qsys_script_path "${ex_design_path}/make_ed_qsys.tcl"
   set qsys_script_log_file  "make_ed_qsys.log"
   set qsys_script_log_path  "$tmp_path/$qsys_script_log_file"

   set platform [lindex $::tcl_platform(platform) 0]

   set search_path_string "\\\$"
   if { [info exists ::env(IMPORT_IP_ROOTDIR) ] } {
      set search_path_string "$::env(IMPORT_IP_ROOTDIR)/altera/emif/**/*,$::env(IMPORT_IP_ROOTDIR)/altera/subsystems/mem_ss_pkg/**/*,\\\$"
   }

   if {$platform == "windows"} {
      set cmd [subst {exec $qsys_script_exe_path --pro --search-path="$search_path_string" --quartus-project=none --cmd="source $params_path" --script=$make_qsys_script_path}]
   } else {
      set cmd [subst {exec $qsys_script_exe_path --pro --search-path='$search_path_string' --quartus-project=none --cmd='source $params_path' --script=$make_qsys_script_path}]
   }
   cd $tmp_path
   set cmd_fail [catch { eval $cmd } tempresult]

   set log_fh [open $qsys_script_log_path "w"]
   puts $log_fh "Ran Command: $cmd"
   puts $log_fh $tempresult
   close $log_fh

   _add_ed_files [list $qsys_script_log_path [get_relative_path $tmp_path $qsys_script_log_path]]

   set fail 0
   if {$gen_sim && ![file exists $sim_qsys_path]} {
      send_message error "An error has occurred when generating the simulation Platform Designer system. See $qsys_script_log_file for details."
      set fail 1
   }
   if {$gen_synth && ![file exists $synth_qsys_path]} {
      send_message error "An error has occurred when generating the synthesis Platform Designer system. See $qsys_script_log_file for details."
      set fail 1
   }
   if {!$fail && [regexp "Error:" $tempresult]} {
      send_message error "An error has occurred when generating the Platform Designer system. See $qsys_script_log_file for details."
      set fail 1
   }
   if {$fail} {
      set ed_files [list]
      foreach ed_file [ls_recursive "${tmp_path}" "*"] {
         lappend ed_files $ed_file [get_relative_path $tmp_path $ed_file]
      }
      _add_ed_files $ed_files
      return
   }


   foreach design_type $design_types {
      set quartus_sh_path  "$::env(QUARTUS_BINDIR)/quartus_sh"
      if { $platform == "windows" } {
         set quartus_sh_path [regsub -all {\\} $quartus_sh_path {/}]
      }
      set make_design_file "make_${design_type}_design.tcl"
      set make_design_path "${ex_design_path}/${make_design_file}"

      file copy $make_design_path $tmp_path

      set gen_log_file "make_${design_type}_design.log"
      set gen_log_path "$tmp_path/$design_type/$gen_log_file"

      set cmd [subst {exec $quartus_sh_path -t "$tmp_path/$make_design_file"}]
      cd $tmp_path
      set cmd_fail [catch { eval $cmd } tempresult]

      set fh [open $gen_log_path "w"]
      puts $fh $tempresult
      close $fh

      if {$cmd_fail == 1} {
         _add_ed_files [list $gen_log_path [get_relative_path $tmp_path $gen_log_path]]
         send_message error "An error has occurred when generating the $design_type example design fileset. See $design_type/$gen_log_file for details."
      }

      set ed_files [list]
      foreach ed_file [ls_recursive "${tmp_path}/${design_type}" "*"] {
         lappend ed_files $ed_file [get_relative_path $tmp_path $ed_file]
      }
      _add_ed_files $ed_files
   }

   _add_ed_files [list "${ex_design_path}/readme.txt" "readme.txt"]

   return 1
}

proc ::mem_ss_pkg::ip_mem_ss::_add_ed_files {src_dest_file_pairs} {
   set files [list \
      [list @     PATH_OR_TEXT   SOURCE   TYPE ] \
   ]

   foreach {src dest} $src_dest_file_pairs {
      switch -glob -nocase -- $dest {
         synth/qdb/* -
         synth/dni/* {
         }
         default {
            lappend files [list $dest PATH $src OTHER]
         }
      }
   }

   table create files $files
}
